using System.Net;using System.Net.Http.Json;using System.Text;using System.Text.Json;using Microsoft.Data.Sqlite;using Microsoft.Extensions.DependencyInjection;namespace DrillingOperations.Tests;
[TestFixture]public sealed class CompletionSelectorTests{static LogObservationSample S(double md,bool good=true)=>new(md,good?40:120,good?2200:2700,good?.22:.02,good?20:.2,good?.22:.5,good?["Valid"]:["BadHole"]);static LogObservationArtifact Log(params LogObservationSample[] samples)=>new("log","run","scenario","path-binding","logs-v1","cal-v1","hash",[],samples,[],new(0,0,0,0,0),"input","output",DateTimeOffset.UtcNow);
[Test]public void Selector_UsesCutoffs_MergesAndCreatesMultipleTypedOpenings(){var samples=Enumerable.Range(0,21).Select(i=>S(i*5,i<=5||i is>=8 and<=11||i>=16)).ToArray();var o=new CompletionDesignOptions{MinimumContiguousThicknessM=5,MergeGapM=4,OpenHoleThicknessThresholdM=25,MinimumIsolationThicknessM=5,MaximumIsolationGapM=30};var x=ObservableCompletionDesigner.Generate("run","RESERVOIR",Log(samples),o);Assert.Multiple(()=>{Assert.That(x.Count(a=>a.Type!="Isolated"),Is.EqualTo(3));Assert.That(x.Any(a=>a.Type=="OpenHole"),Is.True);Assert.That(x.Any(a=>a.Type=="Perforated"),Is.True);Assert.That(x.Any(a=>a.Type=="Isolated"),Is.True);Assert.That(x.All(a=>a.ReservoirName=="RESERVOIR"&&a.BaseMdM>a.TopMdM),Is.True);});}
[Test]public void Selector_MergesSmallGap_AndNoPayFailsWithoutFallback(){LogObservationSample[] merge=[S(0),S(5),S(10,false),S(15),S(20)];var x=ObservableCompletionDesigner.Generate("run","R",Log(merge),new(){MinimumContiguousThicknessM=4,MergeGapM=6,OpenHoleThicknessThresholdM=100});Assert.That(x.Count(a=>a.Type!="Isolated"),Is.EqualTo(1));Assert.Throws<RunStageFailureException>(()=>ObservableCompletionDesigner.Generate("run","R",Log(S(0,false),S(10,false)),new()));}
[Test]public void OptionsAndCalibration_AreValidatedAndChangeIdentityInput(){Assert.Throws<Microsoft.Extensions.Options.OptionsValidationException>(()=>new CompletionDesignOptions{CompletionEfficiency=2}.Validate());var a=new CompletionDesignOptions();var b=new CompletionDesignOptions{CalibrationVersion="other"};Assert.That(a.Hash(),Is.Not.EqualTo(b.Hash()));}
}
[TestFixture,NonParallelizable]public sealed class CompletionWorkflowTests{
[Test]public async Task DraftApprovalRestartActorConflictAndS7Boundary_AreSafe(){await using var factory=new ApiFactory();using var client=factory.CreateInternalClient();using var bind=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/scenarios/{TestData.ScenarioId}/bind"){Content=JsonContent.Create(TestData.Binding())};bind.Headers.Add("Idempotency-Key","completion-bind");(await client.SendAsync(bind)).EnsureSuccessStatusCode();using var create=new HttpRequestMessage(HttpMethod.Post,"/drillingoperations/api/runs"){Content=JsonContent.Create(TestData.Run())};create.Headers.Add("Idempotency-Key","completion-run");var created=await client.SendAsync(create);RunResponse run=JsonSerializer.Deserialize<RunResponse>(await created.Content.ReadAsStringAsync(),CanonicalJson.SerializerOptions)!;await Wait(RunStatus.AwaitingApproval,RunStageKind.S6DesignCompletion);var store=factory.Services.GetRequiredService<DrillingOperationsStore>();CompletionDesign draft=(await store.GetCompletionDesignAsync(run.RunId))!;Assert.Multiple(()=>{Assert.That(draft.Status,Is.EqualTo("Draft"));Assert.That(draft.Openings,Is.Not.Empty);Assert.That(draft.BindingMetadata.ProducingConnectionCount,Is.GreaterThan(draft.Openings.Count(x=>x.Type!="Isolated")));Assert.That(draft.CanonicalObservableInputJson,Does.Not.Contain("oilSaturation").And.Not.Contain("grApi").And.Not.Contain("pressurePa"));});using var approve=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{run.RunId}/completion/approve");approve.Headers.Add("Idempotency-Key","approve-1");approve.Headers.Add("X-DrillSim-Human-Actor","operator-a");var approved=await client.SendAsync(approve);Assert.That(approved.StatusCode,Is.EqualTo(HttpStatusCode.Accepted));await Wait(RunStatus.ReadyToReveal,RunStageKind.S7RunProduction);using var replay=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{run.RunId}/completion/approve");replay.Headers.Add("Idempotency-Key","approve-1");replay.Headers.Add("X-DrillSim-Human-Actor","operator-a");Assert.That((await client.SendAsync(replay)).StatusCode,Is.EqualTo(HttpStatusCode.Accepted));using var conflict=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{run.RunId}/completion/approve");conflict.Headers.Add("Idempotency-Key","approve-2");conflict.Headers.Add("X-DrillSim-Human-Actor","operator-b");Assert.That((await client.SendAsync(conflict)).StatusCode,Is.EqualTo(HttpStatusCode.Conflict));using var sameActor=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{run.RunId}/completion/approve");sameActor.Headers.Add("Idempotency-Key","approve-3");sameActor.Headers.Add("X-DrillSim-Human-Actor","operator-a");Assert.That((await client.SendAsync(sameActor)).StatusCode,Is.EqualTo(HttpStatusCode.OK));CompletionDesign final=(await store.GetCompletionDesignAsync(run.RunId))!;Assert.That(final.Status,Is.EqualTo("Approved"));var restart=new DrillingOperationsStore($"Data Source={factory.DatabasePath}",TimeProvider.System);await restart.InitializeAsync();Assert.That(CanonicalJson.Serialize(await restart.GetCompletionDesignAsync(run.RunId)),Is.EqualTo(CanonicalJson.Serialize(final)));string audit=await client.GetStringAsync($"/drillingoperations/api/audit?scenarioId={TestData.ScenarioId}");Assert.Multiple(()=>{Assert.That(audit,Does.Not.Contain("topMdM"));Assert.That(audit,Does.Not.Contain("grApi"));Assert.That(audit,Does.Not.Contain("pressurePa"));});(int publications,int clocks)=await store.GetSideEffectCountsAsync(run.RunId);Assert.That((publications,clocks),Is.EqualTo((0,0)));await using var db=new SqliteConnection($"Data Source={factory.DatabasePath}");await db.OpenAsync();await using var mutation=db.CreateCommand();mutation.CommandText="UPDATE CompletionDesigns SET Status=$status WHERE RunId=$run";mutation.Parameters.AddWithValue("$status","Changed");mutation.Parameters.AddWithValue("$run",run.RunId);Assert.ThrowsAsync<SqliteException>(async()=>await mutation.ExecuteNonQueryAsync());await using var tamper=db.CreateCommand();tamper.CommandText="DROP TRIGGER TR_CompletionDesigns_NoUpdate;UPDATE CompletionDesigns SET OpeningsHash=$hash WHERE RunId=$run";tamper.Parameters.AddWithValue("$hash",TestData.HashA);tamper.Parameters.AddWithValue("$run",run.RunId);await tamper.ExecuteNonQueryAsync();Assert.ThrowsAsync<PersistenceIntegrityException>(async()=>await restart.GetCompletionDesignAsync(run.RunId));async Task Wait(RunStatus status,RunStageKind stage){for(int i=0;i<300;i++){RunResponse x=(await client.GetFromJsonAsync<RunResponse>($"/drillingoperations/api/runs/{run.RunId}",CanonicalJson.SerializerOptions))!;if(x.Status==status&&x.CurrentStage==stage)return;await Task.Delay(25);}Assert.Fail($"Run did not reach {status}/{stage}");}}
}

