[TestFixture,NonParallelizable]public sealed class CompletionStageFailureTests{
[Test]public async Task UnavailableStageA_BlocksS6AndCanResume(){await using var f=new ApiFactory(completionResponder:_=>TestData.Json(HttpStatusCode.ServiceUnavailable,new{}));using var c=f.CreateInternalClient();RunResponse run=await Create(c,"unavailable");RunResponse blocked=await Wait(c,run.RunId,x=>x.Status==RunStatus.AwaitingDependency&&x.CurrentStage==RunStageKind.S6DesignCompletion);Assert.That(blocked.CurrentStage,Is.EqualTo(RunStageKind.S6DesignCompletion));using var resume=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{run.RunId}/resume");resume.Headers.Add("Idempotency-Key","resume-s6");Assert.That((await c.SendAsync(resume)).StatusCode,Is.EqualTo(HttpStatusCode.Accepted));await Wait(c,run.RunId,x=>x.Status==RunStatus.AwaitingDependency&&x.CurrentStage==RunStageKind.S6DesignCompletion);}
[Test]public async Task MalformedStageA_FailsS6_NotS5(){await using var f=new ApiFactory(completionResponder:_=>new(HttpStatusCode.OK){Content=new StringContent("{")});using var c=f.CreateInternalClient();RunResponse run=await Create(c,"malformed");RunResponse failed=await Wait(c,run.RunId,x=>x.Status==RunStatus.Failed);var store=f.Services.GetRequiredService<DrillingOperationsStore>();var stages=await store.GetStagesAsync(run.RunId);Assert.Multiple(()=>{Assert.That(failed.CurrentStage,Is.EqualTo(RunStageKind.S6DesignCompletion));Assert.That(stages.Single(x=>x.Stage==RunStageKind.S5GenerateLogs).Status,Is.EqualTo(StageStatus.Completed));Assert.That(stages.Single(x=>x.Stage==RunStageKind.S6DesignCompletion).Status,Is.EqualTo(StageStatus.Failed));});}
static async Task<RunResponse>Create(HttpClient c,string suffix){using var bind=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/scenarios/{TestData.ScenarioId}/bind"){Content=JsonContent.Create(TestData.Binding())};bind.Headers.Add("Idempotency-Key","bind-"+suffix);(await c.SendAsync(bind)).EnsureSuccessStatusCode();using var create=new HttpRequestMessage(HttpMethod.Post,"/drillingoperations/api/runs"){Content=JsonContent.Create(TestData.Run())};create.Headers.Add("Idempotency-Key","run-"+suffix);var response=await c.SendAsync(create);return JsonSerializer.Deserialize<RunResponse>(await response.Content.ReadAsStringAsync(),CanonicalJson.SerializerOptions)!;}static async Task<RunResponse>Wait(HttpClient c,string id,Func<RunResponse,bool> done){for(int i=0;i<300;i++){var x=(await c.GetFromJsonAsync<RunResponse>($"/drillingoperations/api/runs/{id}",CanonicalJson.SerializerOptions))!;if(done(x))return x;await Task.Delay(25);}throw new AssertionException("Run state timeout.");}}

